create or replace view public.frescura_diario_sku with (security_invoker = true) as
select f.numero_fila, f.celdas from public.frescura_filas f join public.frescura_hojas h on h.id=f.hoja_id where h.nombre='Diario SKU';
grant select on public.frescura_diario_sku to authenticated;

create or replace view public.frescura_resumen with (security_invoker = true) as
select f.numero_fila, f.celdas from public.frescura_filas f join public.frescura_hojas h on h.id=f.hoja_id where h.nombre='Resumen';
grant select on public.frescura_resumen to authenticated;

create or replace view public.frescura_td_skus with (security_invoker = true) as
select f.numero_fila, f.celdas from public.frescura_filas f join public.frescura_hojas h on h.id=f.hoja_id where h.nombre='TD SKUS';
grant select on public.frescura_td_skus to authenticated;

create or replace view public.frescura_if_30_60_dias with (security_invoker = true) as
select f.numero_fila, f.celdas from public.frescura_filas f join public.frescura_hojas h on h.id=f.hoja_id where h.nombre='IF 30 a 60 días';
grant select on public.frescura_if_30_60_dias to authenticated;

create or replace view public.frescura_riesgos_cd with (security_invoker = true) as
select f.numero_fila, f.celdas from public.frescura_filas f join public.frescura_hojas h on h.id=f.hoja_id where h.nombre='Riesgos CD';
grant select on public.frescura_riesgos_cd to authenticated;

create or replace view public.frescura_tendencia_diaria with (security_invoker = true) as
select f.numero_fila, f.celdas from public.frescura_filas f join public.frescura_hojas h on h.id=f.hoja_id where h.nombre='Tendencia diaria';
grant select on public.frescura_tendencia_diaria to authenticated;

create or replace view public.frescura_ka with (security_invoker = true) as
select f.numero_fila, f.celdas from public.frescura_filas f join public.frescura_hojas h on h.id=f.hoja_id where h.nombre='KA';
grant select on public.frescura_ka to authenticated;

create or replace view public.frescura_riesgos_rango_dias with (security_invoker = true) as
select f.numero_fila, f.celdas from public.frescura_filas f join public.frescura_hojas h on h.id=f.hoja_id where h.nombre='Riesgos rango días';
grant select on public.frescura_riesgos_rango_dias to authenticated;

create or replace view public.frescura_reporte with (security_invoker = true) as
select f.numero_fila, f.celdas from public.frescura_filas f join public.frescura_hojas h on h.id=f.hoja_id where h.nombre='Reporte';
grant select on public.frescura_reporte to authenticated;

